const ASSETS={"/index.html":{"body":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Content Planner</title><style>\n:root{--ink:#152b2c;--green:#244f43;--border:#dedbd1;--paper:#fffefa}*{box-sizing:border-box}body{margin:0;background:#f4f2e9;color:var(--ink);font:14px Arial,sans-serif}header{background:var(--paper);border-top:3px solid #dad7cc;border-bottom:1px solid #e8e5dc;padding:20px 4%;display:flex;justify-content:space-between;align-items:center}.eyebrow{font-size:10px;letter-spacing:2px;margin-bottom:9px}h1,h2{font-family:Georgia,serif;margin:0;color:#081b20}h1{font-size:28px}h2{font-size:23px}button,input,select,textarea{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid var(--green);outline-offset:3px}.primary{background:var(--green);color:white;border:0;border-radius:6px;padding:13px 18px;font-weight:600}.primary span{font-size:20px;margin-right:9px;font-weight:400}main{max-width:1300px;margin:auto;padding:24px 5% 35px;background:radial-gradient(ellipse at top right,#e8ead9,transparent 55%)}.snapshot{display:flex;justify-content:space-between;align-items:end;margin-bottom:17px}.muted{color:#838b88;font-size:12px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:24px}.stat{background:var(--paper);border:1px solid var(--border);border-radius:9px;padding:14px;box-shadow:0 5px 15px #202a2410}.stat label{display:block;margin-bottom:8px}.stat strong{font:28px Georgia,serif;color:#051b24}.pending{background:#fff8df;color:#946700}.approved{background:#edf6e9;color:#246348}.revision{background:#fff0e9;color:#b34328}.planner{background:var(--paper);border:1px solid var(--border);border-radius:9px;overflow:hidden;box-shadow:0 8px 24px #20352a08}.toolbar{padding:16px}.topbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}.tabs{display:flex;gap:20px}.tab{border:0;background:none;padding:7px 0;color:#697674}.tab.active{color:var(--ink);border-bottom:2px solid #799a8c}.monthnav{display:flex;align-items:center;gap:9px;font-size:12px}.arrow{border:1px solid var(--border);border-radius:6px;background:var(--paper);width:30px;height:30px}.filters{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:8px}input,select,textarea{min-width:0;border:1px solid var(--border);border-radius:6px;background:var(--paper);padding:10px;color:var(--ink)}.search{position:relative}.search input{width:100%;padding-left:32px}.search span{position:absolute;left:11px;top:10px;color:#87928b}.sort{display:flex;justify-content:flex-end;align-items:center;gap:8px;margin-top:12px;font-size:12px}.sort select{padding:4px;font-size:12px}.weekdays,.calendar{display:grid;grid-template-columns:repeat(7,minmax(0,1fr))}.weekdays{background:#eeece3;text-align:center;color:#647475}.weekdays div{padding:13px 0;font-size:12px}.day{min-height:105px;padding:10px;border-right:1px solid #e7e3d9;border-bottom:1px solid #e7e3d9;cursor:pointer}.day:nth-child(7n){border-right:0}.day:hover{background:#f8f8f0}.day.outside{background:#f3f1e9;color:#98a09d}.number{font-size:12px;display:inline-flex;align-items:center;justify-content:center;width:23px;height:23px}.today{background:var(--green);border-radius:50%;color:#fff}.event{display:block;width:100%;border:0;border-radius:4px;text-align:left;font-size:12px;line-height:1.5;padding:4px 6px;margin-top:6px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.list{padding:0 16px 16px}.row{display:flex;gap:18px;align-items:center;padding:18px 10px;border-top:1px solid var(--border);cursor:pointer}.row .title{flex:1}.badge{border-radius:4px;padding:6px;font-size:12px}.empty{padding:45px;text-align:center;color:#79877e}dialog{width:480px;max-width:calc(100% - 28px);border:1px solid var(--border);border-radius:12px;padding:24px;background:var(--paper);color:var(--ink);box-shadow:0 20px 80px #0003}dialog::backdrop{background:#122a2755}dialog h2{margin-bottom:22px}.formgrid{display:grid;grid-template-columns:1fr 1fr;gap:14px}form label{display:flex;flex-direction:column;gap:7px}.full{grid-column:1/-1}.actions{display:flex;justify-content:end;gap:9px;margin-top:22px}.secondary{border:1px solid var(--border);background:transparent;border-radius:6px;padding:10px 14px}.delete{margin-right:auto;color:#b34328}.notice{font-size:12px;color:#78847d;margin:20px 0 0} @media(min-width:1400px){.day{min-height:125px}}@media(max-width:650px){header{padding:18px}h1{font-size:25px}.primary{padding:10px;font-size:12px}main{padding:20px 12px}.stats{grid-template-columns:1fr 1fr}.filters{grid-template-columns:1fr 1fr}.search{grid-column:1/-1}.day{min-height:85px;padding:4px}.event{font-size:10px;padding:3px}.weekdays div{font-size:11px}.monthnav{gap:4px}.row{flex-wrap:wrap;gap:10px}.row .title{flex-basis:60%}}\ndialog{padding:0;max-height:90vh;overflow:auto;border-radius:9px}.dialoghead{display:flex;align-items:center;justify-content:space-between;padding:20px 22px;border-bottom:1px solid var(--border)}.dialoghead h2{margin:0;font-size:22px}.dialoghead .eyebrow{font-size:10px}.formbody{padding:22px}.actions{position:sticky;bottom:0;background:var(--paper);padding:15px 20px;border-top:1px solid var(--border);margin:0;flex-wrap:wrap}.storage{margin:0;padding:0 20px 15px}.linkbox{padding:12px;border:1px solid var(--border);border-radius:6px}.linkrow{display:flex;gap:8px;margin-top:8px}.linkrow input{flex:1}.linkbox p{font-size:12px;margin:8px 0 0}.linkbox a{display:inline-block;margin-top:8px;color:var(--green)}[hidden]{display:none!important}.comments{border-top:1px solid var(--border);margin-top:22px;padding-top:6px}.comments h3{font:20px Georgia,serif}.comments textarea{display:block;width:100%;margin:8px 0}.comment{background:#f5f4ed;border-radius:6px;padding:12px;margin:10px 0}.comment p{white-space:pre-wrap;overflow-wrap:anywhere;margin:6px 0}.comment time{font-size:12px;color:#758178}.draft{background:#eeede7;color:#5e6b64}.commentempty{color:#78847d;font-size:13px}.headeractions{display:flex;align-items:center;gap:10px}.platformchoices{margin:0;padding:12px;border:1px solid var(--border);border-radius:6px}.platformchoices legend{padding:0 5px}.platformgrid{display:flex;flex-wrap:wrap;gap:12px 20px}.platformgrid label{display:flex;flex-direction:row;align-items:center;gap:7px}.platformgrid input{accent-color:var(--green);width:16px;height:16px}.platformchoices p{color:#b34328;font-size:12px}.requestintro{margin:0;color:#6b7973;line-height:1.5}.requested{background:#e9eff8;color:#365876}@media(max-width:650px){header{gap:12px;align-items:start}.headeractions{flex-direction:column;align-items:stretch}.headeractions .secondary{font-size:12px;padding:10px}.formgrid{grid-template-columns:1fr}}.requestfields{display:grid;gap:16px}.brandmanager{border:1px solid var(--border);border-radius:6px;padding:12px}.brandmanager summary{cursor:pointer;color:var(--green)}.brandrow{display:flex;gap:8px;margin-top:8px}.brandrow input{flex:1}.brandrow button{padding:7px 9px;font-size:12px}#brandmessage{font-size:12px}.brandmanager .notice{margin:10px 0}.platformgrid label{line-height:1.4}.requestcolor{background:#dceafb;color:#244f83}.scheduledcolor{background:#fff1bf;color:#7a5700}.loadstate{padding:20px 5%;color:#6b7973}.reviewpanel{padding:0 22px 20px}.reviewpanel p{font-size:14px}.reviewpanel .notice{margin:8px 0}input:disabled,select:disabled,textarea:disabled{opacity:1;color:var(--ink);background:#f5f4ed;cursor:default}.day.readonly{cursor:default}</style></head><body><header><div><div class=\"eyebrow\">QUICK OVERVIEW</div><h1>Content Planner</h1></div><div class=\"headeractions\"><button class=\"secondary\" id=\"request\" hidden>+ Request a Content</button><button class=\"primary\" id=\"new\" hidden><span>+</span>New content item</button></div></header><p class=\"loadstate\" id=\"loadstate\" role=\"status\">Loading your planner…</p><main hidden><div class=\"snapshot\"><div><div class=\"eyebrow\">PLANNER SNAPSHOT</div><h2>Your publishing pulse</h2></div><span class=\"muted\" id=\"saved\"></span></div><div class=\"stats\"><div class=\"stat\"><label>Total scheduled</label><strong id=\"total\">1</strong></div><div class=\"stat pending\"><label>Pending review</label><strong id=\"pending\">1</strong></div><div class=\"stat approved\"><label>Approved</label><strong id=\"approved\">0</strong></div><div class=\"stat revision\"><label>Revision requested</label><strong id=\"revision\">0</strong></div></div><section class=\"planner\"><div class=\"toolbar\"><div class=\"topbar\"><div class=\"tabs\"><button class=\"tab active\" id=\"schedule\">Schedule</button><button class=\"tab\" id=\"listtab\">List view</button></div><div class=\"monthnav\"><button class=\"arrow\" id=\"prev\" aria-label=\"Previous month\">‹</button><strong id=\"month\"></strong><button class=\"arrow\" id=\"next\" aria-label=\"Next month\">›</button></div></div><div class=\"filters\"><div class=\"search\"><span aria-hidden=\"true\">⌕</span><input id=\"search\" aria-label=\"Search content\" type=\"search\"></div><select id=\"pillar\" aria-label=\"Filter by pillar\"><option value=\"\">All pillars</option><option>Educational</option><option>Promotional</option><option>Product Showcase</option><option>Testimonial</option><option>Behind the Scenes</option><option>Engagement</option><option>Event Coverage</option><option>Tips</option><option>Education</option><option>Promotion</option><option>Community</option></select><select id=\"platform\" aria-label=\"Filter by platform\"><option value=\"\">All platforms</option><option>Website</option><option>Other</option><option>Instagram</option><option>LinkedIn</option><option>TikTok</option><option>YouTube</option><option>Facebook</option></select><select id=\"status\" aria-label=\"Filter by status\"><option value=\"\">All statuses</option><option>Draft</option><option>Content requested</option><option>Pending review</option><option>Approved</option><option>Revision requested</option></select></div><div class=\"sort\">Sort by date<select id=\"sort\" aria-label=\"Sort by date\"><option value=\"asc\">Earliest first</option><option value=\"desc\">Latest first</option></select></div></div><div id=\"view\"></div></section></main><dialog id=\"editor\" aria-labelledby=\"dialogtitle\"><form id=\"form\"><div class=\"dialoghead\"><div><div class=\"eyebrow\">CONTENT ENTRY</div><h2 id=\"dialogtitle\">Plan a content item</h2></div><button type=\"button\" class=\"arrow\" id=\"close\" aria-label=\"Close form\">×</button></div><div class=\"formbody\"><div class=\"formgrid\"><p class=\"full requestintro\" id=\"requestintro\" hidden>Describe the content you would like created for upload.</p><label class=\"full\"><span id=\"titlelabel\">Content title</span><input name=\"title\" required maxlength=\"120\"></label><div class=\"requestfields full\" id=\"requestfields\" hidden><label>Requested By<input name=\"requestedBy\" id=\"requestedBy\" maxlength=\"100\" placeholder=\"Your name\"></label><fieldset class=\"platformchoices\"><legend>Content Type — choose one or more</legend><div class=\"platformgrid\"><label><input name=\"contentTypes\" type=\"checkbox\" value=\"Short-Form Video\">Short-Form Video</label><label><input name=\"contentTypes\" type=\"checkbox\" value=\"Reel\">Reel</label><label><input name=\"contentTypes\" type=\"checkbox\" value=\"TikTok\">TikTok</label><label><input name=\"contentTypes\" type=\"checkbox\" value=\"YouTube Short\">YouTube Short</label><label><input name=\"contentTypes\" type=\"checkbox\" value=\"YouTube Long-Form Video\">YouTube Long-Form Video</label><label><input name=\"contentTypes\" type=\"checkbox\" value=\"Photo Post\">Photo Post</label><label><input name=\"contentTypes\" type=\"checkbox\" value=\"Carousel\">Carousel</label><label><input name=\"contentTypes\" type=\"checkbox\" value=\"Story\">Story</label><label><input name=\"contentTypes\" type=\"checkbox\" value=\"Promotional Graphic\">Promotional Graphic</label><label><input name=\"contentTypes\" type=\"checkbox\" value=\"Educational Graphic\">Educational Graphic</label><label><input name=\"contentTypes\" type=\"checkbox\" value=\"Blog\">Blog</label><label><input name=\"contentTypes\" type=\"checkbox\" value=\"Website Content\">Website Content</label><label><input name=\"contentTypes\" type=\"checkbox\" value=\"Other\">Other</label></div><p id=\"typeerror\" role=\"alert\" hidden>Select at least one content type.</p></fieldset></div><fieldset class=\"platformchoices full\"><legend>Platforms — choose one or more</legend><div class=\"platformgrid\"><label><input type=\"checkbox\" name=\"platforms\" value=\"Instagram\">Instagram</label><label id=\"legacyplatform\"><input type=\"checkbox\" name=\"platforms\" value=\"LinkedIn\">LinkedIn</label><label><input type=\"checkbox\" name=\"platforms\" value=\"TikTok\">TikTok</label><label><input type=\"checkbox\" name=\"platforms\" value=\"YouTube\">YouTube</label><label><input type=\"checkbox\" name=\"platforms\" value=\"Facebook\">Facebook</label><label><input type=\"checkbox\" name=\"platforms\" value=\"Website\">Website</label><label><input type=\"checkbox\" name=\"platforms\" value=\"Other\">Other</label></div><p id=\"platformerror\" role=\"alert\" hidden>Select at least one platform.</p></fieldset><label>Content pillar<select name=\"pillar\" id=\"entrypillar\" required><option value=\"\">Choose content pillar</option><option>Education</option><option>Promotion</option><option>Community</option></select></label><label><span id=\"datelabel\">Scheduled date</span><input name=\"date\" type=\"date\" required></label><label><span id=\"timelabel\">Scheduled time</span><input name=\"time\" type=\"time\" required></label><label class=\"full\">Caption or content brief<textarea name=\"notes\" rows=\"3\"></textarea></label><label class=\"full\" id=\"approvalfield\">Approval status<select name=\"status\"><option>Draft</option><option>Pending review</option><option>Approved</option><option>Revision requested</option></select></label><div class=\"full linkbox\" id=\"videofield\"><label id=\"drivelabel\" for=\"videoLink\">Google Drive video link</label><div class=\"linkrow\"><input name=\"videoLink\" id=\"videoLink\" type=\"url\" placeholder=\"https://drive.google.com/…\" aria-label=\"Google Drive link\"><button type=\"button\" class=\"secondary\" id=\"applylink\">Apply link</button></div><p id=\"linkfeedback\" role=\"status\"></p><a id=\"openlink\" target=\"_blank\" rel=\"noopener noreferrer\" hidden>Open in Google Drive ↗</a></div></div><section class=\"comments\"><h3>Comments</h3><div id=\"commentlist\" aria-live=\"polite\"></div><label for=\"commenttext\">Add a comment</label><textarea id=\"commenttext\" rows=\"3\" maxlength=\"2000\" placeholder=\"Write feedback or a note…\"></textarea><button type=\"button\" class=\"secondary\" id=\"addcomment\">Add comment</button><p class=\"notice\">Comments are saved with the content item.</p></section></div><div id=\"reviewpanel\" class=\"reviewpanel\" hidden><p id=\"currentstatus\"></p><div id=\"reviewhistory\"></div><button type=\"button\" class=\"primary\" id=\"approve\">Approve content</button> <button type=\"button\" class=\"secondary\" id=\"revise\">Request revision</button><p id=\"reviewmessage\" role=\"status\"></p></div><div class=\"actions\"><button type=\"button\" class=\"secondary delete\" id=\"delete\">Delete item</button><button type=\"button\" class=\"secondary\" id=\"cancel\">Cancel</button><button class=\"primary\" id=\"submititem\" type=\"submit\">Save content item</button></div><p class=\"notice storage\">Items, comments, and review decisions are shared with everyone who has access.</p></form></dialog><script src=\"app.js\"></script></body></html>\n","type":"text/html; charset=utf-8"},"/app.js":{"body":"const $=id=>document.getElementById(id);let items=[],user=null,legacyItems=[];try{legacyItems=JSON.parse(localStorage.getItem('content-planner-v1'))||[]}catch{}const requestPillars=[\"Educational\",\"Promotional\",\"Product Showcase\",\"Testimonial\",\"Behind the Scenes\",\"Engagement\",\"Event Coverage\",\"Tips\"];let month=new Date(2026,8,1),mode='schedule',editing=null,draftComments=[],requestMode=false;const classes={'Pending review':'pending','Approved':'approved','Revision requested':'revision','Draft':'draft','Content requested':'requested'};const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;function filtered(){return items.filter(i=>(!$('search').value||`${i.title} ${i.notes}`.toLowerCase().includes($('search').value.toLowerCase()))&&['pillar','platform','status'].every(k=>!$(k).value||(k==='platform'?platformsFor(i).includes($(k).value):i[k]===$(k).value))).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)*($('sort').value==='asc'?1:-1))}function render(){ $('saved').textContent=`${items.length} saved item${items.length===1?'':'s'}`;$('total').textContent=items.length;for(const k of ['pending','approved','revision'])$(k).textContent=items.filter(i=>classes[i.status]===k).length;$('month').textContent=month.toLocaleDateString('en-US',{month:'long',year:'numeric'});$('schedule').classList.toggle('active',mode==='schedule');$('listtab').classList.toggle('active',mode==='list');const view=$('view');view.replaceChildren();const visible=filtered();if(mode==='schedule'){const weekdays=document.createElement('div');weekdays.className='weekdays';for(const name of ['Sun','Mon','Tue','Wed','Thu','Fri','Sat']){const el=document.createElement('div');el.textContent=name;weekdays.append(el)}view.append(weekdays);const grid=document.createElement('div');grid.className='calendar';const start=new Date(month);start.setDate(1-start.getDay());for(let n=0;n<42;n++){const d=new Date(start);d.setDate(start.getDate()+n);const date=iso(d);const cell=document.createElement('div');cell.className='day'+(d.getMonth()!==month.getMonth()?' outside':'');const num=document.createElement('span');num.className='number'+(date===iso(new Date())?' today':'');num.textContent=d.getDate();cell.append(num);cell.onclick=()=>{if(user?.role==='manager')open(null,date)};if(user?.role!=='manager')cell.classList.add('readonly');for(const item of visible.filter(i=>i.date===date)){const event=document.createElement('button');event.className='event '+(item.kind==='request'?'requestcolor':'scheduledcolor');event.textContent=`${item.time} ▸ ${item.title}`;event.title=`${item.kind==='request'?'Content request':'Scheduled content'} · ${item.title} · ${platformsFor(item).join(', ')} · ${item.status}`;event.onclick=e=>{e.stopPropagation();open(item)};cell.append(event)}grid.append(cell)}view.append(grid)}else{const list=document.createElement('div');list.className='list';const results=visible.filter(i=>i.date.slice(0,7)===iso(month).slice(0,7));for(const item of results){const row=document.createElement('div');row.className='row';const date=document.createElement('span');date.textContent=`${item.date} · ${item.time}`;const title=document.createElement('strong');title.className='title';title.textContent=item.title;const platform=document.createElement('span');platform.textContent=platformsFor(item).join(', ');const badge=document.createElement('span');badge.className='badge '+(item.kind==='request'?'requestcolor':'scheduledcolor');badge.textContent=item.kind==='request'?'Content request':'Scheduled content';row.append(date,title,platform,badge);row.tabIndex=0;row.setAttribute('role','button');row.onclick=()=>open(item);row.onkeydown=e=>{if(e.key==='Enter')open(item)};list.append(row)}if(!results.length){const empty=document.createElement('div');empty.className='empty';empty.textContent='No content matches this month and filters.';list.append(empty)}view.append(list)}}function platformsFor(item){return Array.isArray(item.platforms)?item.platforms:(item.platform?[item.platform]:[])}function open(item,date,isRequest=false){if(!user)return;if(!item&&user.role!=='manager'&&!isRequest)return;requestMode=isRequest||item?.kind==='request';editing=item?.id||null;$('form').reset();$('dialogtitle').textContent=requestMode?(item?'Edit content request':'Request a Content'):(item?'Edit content item':'Plan a content item');$('requestintro').hidden=!requestMode;$('requestfields').hidden=!requestMode;$('approvalfield').hidden=requestMode;$('form').elements.namedItem('status').disabled=requestMode;$('videofield').hidden=false;$('videoLink').disabled=false;$('drivelabel').textContent=requestMode?'Google Drive reference link (optional)':'Google Drive video link';$('videoLink').setCustomValidity('');$('requestedBy').required=requestMode;$('titlelabel').textContent=requestMode?'Content Title / Request Name':'Content title';$('form').elements.namedItem('title').placeholder=requestMode?'P2.6 LED Wall Educational Video':'';$('legacyplatform').hidden=requestMode&&!platformsFor(item||{}).includes('LinkedIn');populatePillars(item?.pillar||'');$('typeerror').hidden=true;for(const box of document.querySelectorAll('input[name=contentTypes]')){box.disabled=!requestMode;box.checked=(item?.contentTypes||[]).includes(box.value)}$('datelabel').textContent=requestMode?'Requested upload date':'Scheduled date';$('timelabel').textContent=requestMode?'Requested upload time':'Scheduled time';$('submititem').textContent=requestMode?'Save content request':'Save content item';$('platformerror').hidden=true;for(const box of document.querySelectorAll('input[name=platforms]'))box.checked=platformsFor(item||{}).includes(box.value);draftComments=structuredClone(item?.comments||[]);$('commenttext').value='';renderComments();$('linkfeedback').textContent='';$('openlink').hidden=true;$('delete').hidden=!item;const values=item||{date:date||iso(month),time:'09:00'};for(const [key,value]of Object.entries(values)){const el=$('form').elements.namedItem(key);if(el)el.value=key==='pillar'?(({Education:'Educational',Promotion:'Promotional'})[value]||value):value}if(requestMode&&!item)$('form').elements.namedItem('status').value='Content requested';applyLink(false);configureAccess(item);$('editor').showModal()}$('new').onclick=()=>open(null,iso(new Date()));$('cancel').onclick=()=>$('editor').close();$('delete').onclick=async()=>{if(user.role!=='manager'||!editing)return;if(!confirm('Delete this entry and its comments?'))return;try{await api('/api/items/'+encodeURIComponent(editing),'DELETE');$('editor').close();await loadPlanner()}catch(e){alert(e.message)}};$('form').onsubmit=async e=>{e.preventDefault();const platforms=[...document.querySelectorAll('input[name=platforms]:checked')].map(box=>box.value);if(!platforms.length){$('platformerror').hidden=false;document.querySelector('input[name=platforms]').focus();return}const item=Object.fromEntries(new FormData($('form')));item.platforms=platforms;delete item.platform;item.kind=requestMode?'request':'content';if(requestMode){item.status='Content requested';delete item.brand;item.contentTypes=[...document.querySelectorAll('input[name=contentTypes]:checked')].map(box=>box.value);if(!item.contentTypes.length){$('typeerror').hidden=false;document.querySelector('input[name=contentTypes]').focus();return}}else{delete item.brand;delete item.requestedBy;delete item.contentTypes;}item.id=editing||crypto.randomUUID();item.comments=structuredClone(draftComments);try{const previous=items.find(i=>i.id===editing);await api('/api/items'+(editing?'/'+encodeURIComponent(editing):''),editing?'PUT':'POST',{item,version:previous?.version});for(const comment of draftComments.filter(c=>c.pending))await api('/api/items/'+encodeURIComponent(item.id)+'/comments','POST',{text:comment.text});month=new Date(item.date+'T12:00:00');month.setDate(1);$('editor').close();await loadPlanner()}catch(e){alert(e.message)}};for(const id of ['search','pillar','platform','status','sort'])$(id).addEventListener('input',render);$('prev').onclick=()=>{month.setMonth(month.getMonth()-1);render()};$('next').onclick=()=>{month.setMonth(month.getMonth()+1);render()};$('schedule').onclick=()=>{mode='schedule';render()};$('listtab').onclick=()=>{mode='list';render()};\n\nfunction renderComments(){const list=$('commentlist');list.replaceChildren();if(!draftComments.length){const empty=document.createElement('p');empty.className='commentempty';empty.textContent='No comments yet.';list.append(empty)}for(const comment of draftComments){const el=document.createElement('article');el.className='comment';const time=document.createElement('time');time.dateTime=comment.createdAt;time.textContent=(comment.author?comment.author+' · ':'')+new Date(comment.createdAt).toLocaleString();const body=document.createElement('p');body.textContent=comment.text;el.append(time,body);list.append(el)}}\n$('addcomment').onclick=async()=>{const text=$('commenttext').value.trim();if(!text){$('commenttext').focus();return}try{if(editing){await api('/api/items/'+encodeURIComponent(editing)+'/comments','POST',{text});await loadPlanner();draftComments=structuredClone(items.find(i=>i.id===editing)?.comments||[])}else draftComments.push({id:crypto.randomUUID(),text,author:user.name,createdAt:new Date().toISOString(),pending:true});$('commenttext').value='';renderComments()}catch(e){alert(e.message)}};\nfunction applyLink(feedback=true){const input=$('videoLink');const value=input.value.trim();$('openlink').hidden=true;input.setCustomValidity('');if(!value){if(feedback)$('linkfeedback').textContent='Enter a Google Drive link.';return}let url;try{url=new URL(value)}catch{}if(!url||url.protocol!=='https:'||url.hostname!=='drive.google.com'){input.setCustomValidity('Use an HTTPS link from drive.google.com.');if(feedback)input.reportValidity();return}$('openlink').href=url.href;$('openlink').hidden=false;if(feedback)$('linkfeedback').textContent='Link applied. Save the item to keep it.'}\n$('applylink').onclick=()=>applyLink();$('videoLink').oninput=()=>{$('videoLink').setCustomValidity('');$('openlink').hidden=true;$('linkfeedback').textContent=''};$('close').onclick=()=>$('editor').close();\n\n$('request').onclick=()=>open(null,iso(new Date()),true);for(const box of document.querySelectorAll('input[name=platforms]'))box.onchange=()=>{$('platformerror').hidden=true};\n\nfunction populatePillars(selected=''){selected=({Education:'Educational',Promotion:'Promotional'})[selected]||selected;const select=$('entrypillar');select.replaceChildren();const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent='Choose content pillar';select.append(placeholder);for(const name of [...new Set([...requestPillars,...(requestMode?[]:['Community']),...(selected?[selected]:[])])]){const option=document.createElement('option');option.value=name;option.textContent=name;select.append(option)}select.value=selected;}\nfor(const box of document.querySelectorAll('input[name=contentTypes]'))box.onchange=()=>{$('typeerror').hidden=true};\n\nasync function api(path,method='GET',data){const response=await fetch(path,{method,headers:{'Content-Type':'application/json'},...(data?{body:JSON.stringify(data)}:{})});let body;try{body=await response.json()}catch{throw Error('Could not connect to the planner. Please try again.')}if(!response.ok)throw Error(body.error||'Action failed.');return body}\nasync function loadPlanner(){const result=await api('/api/planner');user=result.user;items=result.items;$('new').hidden=user.role!=='manager';$('request').hidden=false;document.querySelector('main').hidden=false;$('loadstate').hidden=true;render();if(editing)renderReview(items.find(i=>i.id===editing));}\nfunction configureAccess(item){const viewing=!!item&&user.role!=='manager';for(const field of document.querySelectorAll('#form .formgrid input, #form .formgrid select, #form .formgrid textarea'))field.disabled=viewing;for(const field of document.querySelectorAll('#requestfields input, #requestfields select'))field.disabled=viewing||!requestMode;$('form').elements.namedItem('status').disabled=viewing||requestMode;$('videoLink').disabled=viewing;$('applylink').hidden=viewing;$('submititem').hidden=viewing;$('delete').hidden=!item||user.role!=='manager';$('cancel').textContent=viewing?'Close':'Cancel';if(viewing)$('dialogtitle').textContent=item.kind==='request'?'Content request':'View content item';if(!item&&requestMode)$('requestedBy').value=user.name;renderReview(item);}\nfunction renderReview(item){$('reviewpanel').hidden=!item||item.kind==='request';$('reviewmessage').textContent='';$('reviewhistory').replaceChildren();if(!item)return;$('currentstatus').textContent='Approval status: '+item.status;for(const review of item.reviews||[]){const line=document.createElement('p');line.className='notice';line.textContent=review.author+' · '+review.decision+' · '+new Date(review.createdAt).toLocaleString();$('reviewhistory').append(line)}}\nasync function review(decision){if(!editing)return;try{await api('/api/items/'+encodeURIComponent(editing)+'/review','POST',{decision});await loadPlanner();$('reviewmessage').textContent=decision==='Approved'?'Content approved.':'Revision requested.'}catch(e){$('reviewmessage').textContent=e.message}}\n$('approve').onclick=()=>review('Approved');$('revise').onclick=()=>review('Revision requested');\n(async()=>{try{await loadPlanner();if(user.role==='manager'&&!items.length&&Array.isArray(legacyItems)&&legacyItems.length){await api('/api/import','POST',{items:legacyItems});await loadPlanner()}}catch(e){$('loadstate').hidden=false;$('loadstate').textContent=e.message+' Refresh to try again.'}})();\n","type":"text/javascript; charset=utf-8"}};
const OWNER_EMAIL='tldj.cavite@gmail.com';
const json=(data,status=200)=>Response.json(data,{status,headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
const fail=(status,message)=>{throw Object.assign(new Error(message),{status})};
function db(env){if(!env.DB)fail(503,'Shared planner is unavailable. Please try again.');return env.DB;}
async function identity(request,env){const id=request.headers.get('oai-authenticated-user-id');if(!id)fail(401,'Sign in to use the planner.');const email=request.headers.get('oai-authenticated-user-email')||'';let name=email;try{if(request.headers.get('oai-authenticated-user-full-name-encoding')==='percent-encoded-utf-8')name=decodeURIComponent(request.headers.get('oai-authenticated-user-full-name')||email)}catch{}const store=db(env);let manager=await store.prepare('SELECT id FROM managers WHERE id=?').bind(id).first();if(!manager&&email.toLowerCase()===OWNER_EMAIL){await store.prepare('INSERT OR IGNORE INTO managers(id) VALUES(?)').bind(id).run();manager={id};}return {id,name:name||'Reviewer',role:manager?'manager':'visitor'};}
function clean(data){const text=(k,max,required=false)=>{const value=typeof data[k]==='string'?data[k].trim():'';if(value.length>max||(required&&!value))fail(400,'Check the '+k+' field.');return value};const item={id:text('id',100,true),title:text('title',120,true),date:text('date',10,true),time:text('time',5,true),pillar:text('pillar',100,true),notes:text('notes',10000),videoLink:text('videoLink',2048),kind:data.kind==='request'?'request':'content',status:text('status',50)||'Draft'};if(!/^\d{4}-\d{2}-\d{2}$/.test(item.date)||!/^\d{2}:\d{2}$/.test(item.time))fail(400,'Choose a date and time.');item.platforms=Array.isArray(data.platforms)?data.platforms:typeof data.platform==='string'?[data.platform]:[];if(!item.platforms.length||item.platforms.length>8||item.platforms.some(x=>!['Instagram','Facebook','TikTok','YouTube','LinkedIn','Website','Other'].includes(x)))fail(400,'Choose valid platforms.');if(!['Draft','Pending review','Approved','Revision requested','Content requested'].includes(item.status))fail(400,'Choose a valid status.');if(item.videoLink){let url;try{url=new URL(item.videoLink)}catch{}if(!url||url.protocol!=='https:'||url.hostname!=='drive.google.com')fail(400,'Use a Google Drive HTTPS link.');}if(item.kind==='request'){item.requestedBy=text('requestedBy',100,true);item.contentTypes=Array.isArray(data.contentTypes)?data.contentTypes:[];if(!item.contentTypes.length||item.contentTypes.length>13||item.contentTypes.some(x=>typeof x!=='string'||x.length>100))fail(400,'Choose content types.');}return item;}
async function allItems(env){const store=db(env);const [rows,comments,decisions]=await Promise.all([store.prepare('SELECT payload,updated FROM content ORDER BY id').all(),store.prepare('SELECT * FROM feedback ORDER BY created_at').all(),store.prepare('SELECT * FROM reviews ORDER BY created_at').all()]);return rows.results.map(row=>{const item=JSON.parse(row.payload);return {...item,version:row.updated,comments:comments.results.filter(c=>c.content_id===item.id).map(c=>({id:c.id,text:c.text,author:c.author,createdAt:c.created_at})),reviews:decisions.results.filter(r=>r.content_id===item.id).map(r=>({author:r.author,decision:r.decision,createdAt:r.created_at}))}})}
async function body(request){const text=await request.text();if(text.length>250000)fail(413,'This request is too large.');try{return JSON.parse(text)}catch{fail(400,'Invalid request.')}}
export default {async fetch(request,env){try{const url=new URL(request.url);if(!url.pathname.startsWith('/api/')){const asset=ASSETS[url.pathname==='/'?'/index.html':url.pathname];if(!asset)return new Response('Not found',{status:404});return new Response(asset.body,{headers:{'Content-Type':asset.type,'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}})}const user=await identity(request,env);if(request.method!=='GET'&&request.headers.get('Origin')!==url.origin)fail(403,'Please submit from the planner page.');const store=db(env);if(url.pathname==='/api/planner'&&request.method==='GET')return json({user,items:await allItems(env)});
if(url.pathname==='/api/import'&&request.method==='POST'){if(user.role!=='manager')fail(403,'Only a manager can import items.');const data=await body(request);if(!Array.isArray(data.items)||data.items.length>500)fail(400,'Invalid import.');const count=await store.prepare('SELECT count(*) AS n FROM content').first();if(count.n)return json({imported:false});const statements=[];for(const raw of data.items){const item=clean({...raw,requestedBy:raw.requestedBy||user.name,contentTypes:raw.contentTypes?.length?raw.contentTypes:['Other']});statements.push(store.prepare('INSERT OR IGNORE INTO content(id,payload,updated) VALUES(?,?,?)').bind(item.id,JSON.stringify(item),crypto.randomUUID()));for(const c of raw.comments||[]){if(typeof c.text!=='string'||!c.text.trim())continue;statements.push(store.prepare('INSERT OR IGNORE INTO feedback(id,content_id,user_id,author,text,created_at) VALUES(?,?,?,?,?,?)').bind(c.id||crypto.randomUUID(),item.id,user.id,c.author||user.name,c.text.slice(0,2000),c.createdAt||new Date().toISOString()));}}if(statements.length)await store.batch(statements);return json({imported:true});}
if(url.pathname==='/api/items'&&request.method==='POST'){const data=await body(request);const item=clean(data.item||{});if(user.role!=='manager'){if(item.kind!=='request')fail(403,'Only managers can create scheduled content.');item.status='Content requested';item.requestedBy=user.name;}await store.prepare('INSERT INTO content(id,payload,updated) VALUES(?,?,?)').bind(item.id,JSON.stringify(item),crypto.randomUUID()).run();return json({ok:true});}
const match=url.pathname.match(/^\/api\/items\/([^/]+)(?:\/(comments|review))?$/);if(!match)fail(404,'Not found.');const id=decodeURIComponent(match[1]);const existing=await store.prepare('SELECT payload,updated FROM content WHERE id=?').bind(id).first();if(!existing)fail(404,'This item has been removed.');const current=JSON.parse(existing.payload);
if(match[2]==='comments'&&request.method==='POST'){const data=await body(request);if(typeof data.text!=='string'||!data.text.trim()||data.text.length>2000)fail(400,'Write a comment of up to 2,000 characters.');await store.prepare('INSERT INTO feedback(id,content_id,user_id,author,text,created_at) VALUES(?,?,?,?,?,?)').bind(crypto.randomUUID(),id,user.id,user.name,data.text.trim(),new Date().toISOString()).run();return json({ok:true});}
if(match[2]==='review'&&request.method==='POST'){if(current.kind==='request')fail(400,'Only scheduled content can be reviewed.');const data=await body(request);if(!['Approved','Revision requested'].includes(data.decision))fail(400,'Choose approve or request revision.');current.status=data.decision;await store.batch([store.prepare("UPDATE content SET payload=json_set(payload,'$.status',?),updated=? WHERE id=?").bind(data.decision,crypto.randomUUID(),id),store.prepare('INSERT INTO reviews(id,content_id,user_id,author,decision,created_at) VALUES(?,?,?,?,?,?)').bind(crypto.randomUUID(),id,user.id,user.name,data.decision,new Date().toISOString())]);return json({ok:true});}
if(!match[2]&&request.method==='PUT'){if(user.role!=='manager')fail(403,'Visitors cannot edit content.');const data=await body(request);const item=clean({...data.item,id});const result=await store.prepare('UPDATE content SET payload=?,updated=? WHERE id=? AND updated=?').bind(JSON.stringify(item),crypto.randomUUID(),id,data.version||'').run();if(!result.meta.changes)fail(409,'This item changed. Close and reopen it before saving.');return json({ok:true});}
if(!match[2]&&request.method==='DELETE'){if(user.role!=='manager')fail(403,'Visitors cannot delete content.');await store.prepare('DELETE FROM content WHERE id=?').bind(id).run();return json({ok:true});}fail(405,'Action unavailable.');
}catch(error){if(!error.status)console.error('Planner API failure',error.message);return json({error:error.status?error.message:'The planner could not save or load. Please try again.'},error.status||503);}}};
